"""
Tests for GitHub Actions workflow lockfile support (.github/workflows/actions.lock).
"""

from __future__ import annotations

from pathlib import Path

import pytest
from ruamel.yaml import YAML
from typer.testing import CliRunner

from heurix.cli import app
from heurix.core.drift import DriftDetector
from heurix.core.lockfile import LockfileError, load_lockfile, workflow_action_refs
from heurix.core.merger import SmartMerger

LOCK = """# This file is machine-generated by `gh actions-lock`.
# Do not edit by hand; run `gh actions-lock` to update.
version: 'v0.0.3'
workflows:
  '.github/workflows/ci.yml':
    - 'actions/checkout@v7.0.1'
    - 'Actions/Setup-Python@v7.1.0'
    - 'actions/setup-python@v6'
dependencies:
  'actions/checkout@v7.0.1':
    ref: 'v7.0.1'
    commit: '0123456789abcdef0123456789abcdef01234567'
    owner_id: 44036562
    repo_id: 197814629
"""


def _write(root: Path, rel: str, text: str) -> None:
    path = root / rel
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(text, encoding="utf-8")


def test_load_lockfile_reads_onboarded_workflows(tmp_path: Path):
    assert load_lockfile(tmp_path) is None

    _write(tmp_path, ".github/workflows/actions.lock", LOCK)
    lock = load_lockfile(tmp_path)

    assert lock is not None
    assert lock.version == "v0.0.3"
    assert lock.covers(".github/workflows/ci.yml")
    assert lock.covers("./.github/workflows/ci.yml")
    assert not lock.covers(".github/workflows/release.yml")
    # Owner and repo are case-insensitive on GitHub; the ref is not.
    assert lock.missing(
        ".github/workflows/ci.yml",
        ["actions/setup-python@v7.1.0", "actions/checkout@v7", "actions/checkout@v7.0.1"],
    ) == ["actions/checkout@v7"]
    # The highest locked version tag is the one to reuse.
    assert lock.locked_refs(".github/workflows/ci.yml") == {
        "actions/checkout": "v7.0.1",
        "actions/setup-python": "v7.1.0",
    }


@pytest.mark.parametrize(
    ("text", "message"),
    [("workflows: [unclosed", "not valid YAML"), ("version: 'v9'\nentries: {}\n", "no 'workflows' map")],
)
def test_load_lockfile_rejects_unreadable_files(tmp_path: Path, text: str, message: str):
    _write(tmp_path, ".github/workflows/actions.lock", text)

    with pytest.raises(LockfileError, match=message):
        load_lockfile(tmp_path)


def test_workflow_action_refs_lists_only_lockable_step_actions():
    doc = YAML(typ="safe").load(
        """
jobs:
  build:
    runs-on: ubuntu-latest
    steps:
      - uses: actions/checkout@v7
      - uses: ./local-action
      - uses: $/same-repo-action
      - uses: docker://alpine:3.20
      - uses: github/codeql-action/init@v4
      - uses: ${{ matrix.action }}
      - run: echo hi
      - uses: actions/checkout@v7
  shared:
    uses: octo-org/workflows/.github/workflows/ci.yml@v1
"""
    )

    assert workflow_action_refs(doc) == ["actions/checkout@v7", "github/codeql-action/init@v4"]


def test_check_reports_actions_missing_from_the_lockfile(tmp_path: Path):
    _write(tmp_path, ".github/workflows/actions.lock", LOCK)
    _write(
        tmp_path,
        ".github/workflows/ci.yml",
        "jobs:\n  t:\n    runs-on: ubuntu-latest\n    steps:\n"
        "      - uses: actions/checkout@v7.0.1\n      - uses: astral-sh/setup-uv@v10.4.0\n",
    )
    # Not onboarded, so its unlocked action is not a finding.
    _write(
        tmp_path,
        ".github/workflows/docs.yml",
        "jobs:\n  t:\n    runs-on: ubuntu-latest\n    steps:\n      - uses: actions/configure-pages@v5\n",
    )

    findings = DriftDetector(tmp_path)._check_lockfile_coverage()

    assert len(findings) == 1
    assert findings[0].file_path == ".github/workflows/ci.yml"
    assert findings[0].severity == "ERROR"
    assert "astral-sh/setup-uv@v10.4.0" in findings[0].issue
    assert "gh actions-lock" in findings[0].recommendation


def test_check_warns_about_an_unreadable_lockfile(tmp_path: Path):
    _write(tmp_path, ".github/workflows/actions.lock", "- just a list\n")

    findings = DriftDetector(tmp_path)._check_lockfile_coverage()

    assert [(f.file_path, f.severity) for f in findings] == [(".github/workflows/actions.lock", "WARNING")]


_LOCKED_EXISTING = """name: CI
jobs:
  test:
    runs-on: ubuntu-latest
    steps:
      - name: Checkout repository
        uses: actions/checkout@v7.0.1
      - name: Install uv
        uses: astral-sh/setup-uv@v5.4.2
      - name: Run tests
        run: uv run pytest
"""

_GENERATED = """name: CI
jobs:
  test:
    runs-on: ubuntu-latest
    steps:
      - name: Checkout repository
        uses: actions/checkout@v7
      - name: Install uv
        uses: astral-sh/setup-uv@v10.4.0
      - name: Run tests
        run: uv run pytest
  lint:
    runs-on: ubuntu-latest
    steps:
      - name: Checkout repository
        uses: actions/checkout@v7
      - name: Install pnpm
        uses: pnpm/action-setup@v6
"""


def _uses(text: str) -> dict[str, list[str]]:
    doc = YAML(typ="safe").load(text)
    return {job_id: [str(s["uses"]) for s in job["steps"] if "uses" in s] for job_id, job in doc["jobs"].items()}


def test_locked_workflow_keeps_refs_and_reuses_locked_ones():
    merger = SmartMerger()
    merger.locked_action_refs = {"actions/checkout": "v7.0.1", "astral-sh/setup-uv": "v5.4.2"}

    out = merger.merge_yaml(_LOCKED_EXISTING, _GENERATED)

    assert _uses(out) == {
        # setup-uv is older than Heurix's default, but upgrading it would break the locked run.
        "test": ["actions/checkout@v7.0.1", "astral-sh/setup-uv@v5.4.2"],
        # The new job's checkout reuses the locked ref; only pnpm needs relocking.
        "lint": ["actions/checkout@v7.0.1", "pnpm/action-setup@v6"],
    }


def test_unlocked_workflow_still_upgrades_older_refs():
    out = SmartMerger().merge_yaml(_LOCKED_EXISTING, _GENERATED)

    assert _uses(out)["test"] == ["actions/checkout@v7.0.1", "astral-sh/setup-uv@v10.4.0"]


def test_locked_workflow_still_applies_policy_pins():
    merger = SmartMerger(policy_pinned_actions=["astral-sh/setup-uv"])
    merger.locked_action_refs = {"astral-sh/setup-uv": "v5.4.2"}

    assert _uses(merger.merge_yaml(_LOCKED_EXISTING, _GENERATED))["test"][1] == "astral-sh/setup-uv@v10.4.0"


def test_generate_warns_when_a_locked_workflow_gains_unlocked_actions(tmp_path: Path):
    (tmp_path / "requirements.txt").write_text("pytest\n", encoding="utf-8")
    args = ["generate", "--path", str(tmp_path), "--yes", "--no-explain", "--no-k8s"]
    runner = CliRunner()
    assert runner.invoke(app, args).exit_code == 0
    refs = workflow_action_refs(YAML(typ="safe").load((tmp_path / ".github/workflows/ci.yml").read_text()))
    lock_body = "".join(f"    - '{r}'\n" for r in refs)
    _write(
        tmp_path,
        ".github/workflows/actions.lock",
        f"version: 'v0.0.3'\nworkflows:\n  '.github/workflows/ci.yml':\n{lock_body}",
    )

    in_sync = runner.invoke(app, args)
    assert in_sync.exit_code == 0
    assert "actions.lock" not in in_sync.stdout

    (tmp_path / "package.json").write_text('{"name": "w", "scripts": {"test": "vitest"}}', encoding="utf-8")
    (tmp_path / "package-lock.json").write_text("{}", encoding="utf-8")
    grown = runner.invoke(app, args)
    assert grown.exit_code == 0
    out = " ".join(grown.stdout.split())
    assert "which has no entry for: actions/setup-node@v7" in out
    assert "gh actions-lock" in out
    assert "actions/checkout" not in out.split("no entry for:")[1].split("After writing")[0]


def test_renamed_job_in_a_locked_workflow_keeps_locked_refs(tmp_path: Path):
    """A language change renames `test` to `test-python`; the locked refs must survive the rename."""
    (tmp_path / "requirements.txt").write_text("pytest\n", encoding="utf-8")
    args = ["generate", "--path", str(tmp_path), "--yes", "--no-explain", "--no-k8s"]
    runner = CliRunner()
    assert runner.invoke(app, args).exit_code == 0
    ci = tmp_path / ".github/workflows/ci.yml"
    # What `gh actions-lock` does: narrow each ref to a full version and lock it.
    narrowed = ci.read_text().replace("actions/checkout@v7\n", "actions/checkout@v7.0.1\n")
    ci.write_text(narrowed, encoding="utf-8")
    refs = workflow_action_refs(YAML(typ="safe").load(narrowed))
    assert "actions/checkout@v7.0.1" in refs
    lock_body = "".join(f"    - '{r}'\n" for r in refs)
    _write(
        tmp_path,
        ".github/workflows/actions.lock",
        f"version: 'v0.0.3'\nworkflows:\n  '.github/workflows/ci.yml':\n{lock_body}",
    )

    (tmp_path / "package.json").write_text('{"name": "w", "scripts": {"test": "vitest"}}', encoding="utf-8")
    (tmp_path / "package-lock.json").write_text("{}", encoding="utf-8")
    result = runner.invoke(app, args)

    assert result.exit_code == 0
    jobs = _uses(ci.read_text())
    assert set(jobs) == {"test-python", "test-node"}
    assert jobs["test-python"] == refs
    assert jobs["test-node"][0] == "actions/checkout@v7.0.1"
    out = " ".join(result.stdout.split())
    assert "jobs.test: renamed to jobs.test-python" in out
    assert "which has no entry for: actions/setup-node@v7" in out
